import test from 'node:test';
import assert from 'node:assert/strict';
import {Tools} from '../src/tools.mjs';

test('draft candidate queries require observed identity, page real candidates, and reuse one selector without applying',async()=>{const calls=[],tools=new Tools({status:()=>({})},{subprocess:async(_exe,args)=>{calls.push(args);return args.includes('--close')?{closed:true,status:{title:'합성 초안'}}:{window:{hwnd:456},options:{participants:[{name:'합성 기안자'}],candidates:[{name:'가상교사 가',id:'a'},{name:'가상교사 나',id:'b'},{name:'다른 교사',id:'c'}],controls:[]}};}});await assert.rejects(tools.call('wxs.options',{hwnd:'123',expected_title:'합성 초안',section:'approval'}),e=>e.code==='WXS_WINDOW_NOT_OBSERVED');assert.equal(calls.length,0);tools.windows.add('123');let result=await tools.call('wxs.options',{hwnd:'123',expected_title:'합성 초안',section:'approval',query:'가상',limit:1});assert.equal(result.totalCandidates,2);assert.equal(result.hasMore,true);assert.equal(result.options.candidates[0].id,'a');assert.equal(result.readOnly,true);result=await tools.call('wxs.options',{hwnd:'123',expected_title:'합성 초안',section:'approval',query:'가상',offset:1,limit:1});assert.equal(result.options.candidates[0].id,'b');assert.equal(result.hasMore,false);assert(calls[1].includes('--dialog-hwnd'));assert.equal(calls[1][calls[1].indexOf('--dialog-hwnd')+1],'456');await assert.rejects(tools.call('wxs.options',{hwnd:'123',expected_title:'합성 초안',section:'approval',dialog_hwnd:'999'}),e=>e.code==='WXS_DIALOG_NOT_OBSERVED');result=await tools.call('wxs.options',{hwnd:'123',expected_title:'합성 초안',section:'approval',close:true});assert.equal(result.closed,true);assert(calls.at(-1).includes('--close'));assert(calls.every(args=>!args.includes('--apply')&&!args.includes('--confirm-final-action')));await assert.rejects(tools.call('wxs.options',{hwnd:'123',expected_title:'합성 초안',section:'approval',close:true}),e=>e.code==='WXS_OPTIONS_CLOSE');});
